package server

import (
	"context"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// health is the liveness probe (/health). With ?ready=1 it is the readiness
// probe: every dependency registered in s.checks (database, cache) is pinged
// and any failure turns the response into a 503.
func (s *Server) health(c *fiber.Ctx) error {
	if c.Query("ready") == "" {
		return c.JSON(fiber.Map{"ok": true})
	}
	code, body := s.readiness(c.UserContext())
	return c.Status(code).JSON(body)
}

func (s *Server) readiness(ctx context.Context) (int, map[string]any) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	code, body := http.StatusOK, map[string]any{"ok": true}
	for name, check := range s.checks {
		if err := check(ctx); err != nil {
			code, body["ok"], body[name] = http.StatusServiceUnavailable, false, err.Error()
		} else {
			body[name] = "ok"
		}
	}
	return code, body
}

