package server

import (
	"context"
	"log/slog"
	"os"

	"github.com/gofiber/fiber/v2"
	"github.com/your-username/test-app/internal/cache"
	"github.com/your-username/test-app/internal/config"
	"github.com/your-username/test-app/internal/db"
	"github.com/your-username/test-app/internal/monitoring"
	"github.com/your-username/test-app/internal/tracing"
)

type Server struct {
	cfg *config.Config
	log *slog.Logger
	app *fiber.App

	// checks are pinged by /health?ready=1; closers run in reverse on Shutdown.
	checks  map[string]func(context.Context) error
	closers []func(context.Context) error
}

func New(cfg *config.Config, log *slog.Logger) *Server {
	s := &Server{cfg: cfg, log: log, checks: map[string]func(context.Context) error{}}
	if shutdown, err := tracing.Init(context.Background(), cfg.AppName); err != nil {
		log.Warn("tracing disabled", "err", err)
	} else {
		s.closers = append(s.closers, shutdown)
	}
	sqlDB, err := db.Open(cfg.DatabaseURL)
	if err != nil {
		log.Error("database", "err", err)
		os.Exit(1)
	}
	s.checks["db"] = sqlDB.PingContext
	s.closers = append(s.closers, func(context.Context) error { return sqlDB.Close() })
	rdb, err := cache.Open(cfg.RedisURL)
	if err != nil {
		// Not fatal: liveness stays green, /health?ready=1 reports the cache as down.
		log.Warn("cache unavailable at startup", "err", err)
	}
	if rdb != nil {
		s.checks["cache"] = func(ctx context.Context) error { return rdb.Ping(ctx).Err() }
		s.closers = append(s.closers, func(context.Context) error { return rdb.Close() })
	} else {
		cacheErr := err
		s.checks["cache"] = func(context.Context) error { return cacheErr }
	}

	r := fiber.New(fiber.Config{DisableStartupMessage: true})
	r.Use(recoverer(log), tracing.Middleware(cfg.AppName), requestLog(log), rateLimit(), auditLog(log))
	monitoring.MountMetrics(r)

	r.Get("/health", s.health)
	mountGraphQL(r)

	s.app = r
	return s
}

func (s *Server) Run() error {
	return s.app.Listen(":" + s.cfg.Port)
}

// Shutdown drains in-flight requests, then closes dependencies (tracing flush,
// cache, database) in reverse order of opening.
func (s *Server) Shutdown(ctx context.Context) error {
	err := s.app.ShutdownWithContext(ctx)
	for i := len(s.closers) - 1; i >= 0; i-- {
		if cerr := s.closers[i](ctx); cerr != nil {
			s.log.Warn("shutdown", "err", cerr)
		}
	}
	return err
}

func (s *Server) App() *fiber.App { return s.app }

